/** Every wasm export returns this envelope as a plain object. */
export type Result<T> = { ok: true; value: T } | { ok: false; errors: CoreError[] };

export type CoreError = { code: string, message: string, 
/**
 * Config key (dotted) or output-relative file the error concerns.
 */
path?: string, };

export type SiteConfig = { site: Site, identity: Identity, contentSignal: ContentSignal, bots: Array<BotPolicy>, content: Content, llms: Llms, env: Array<string>, headers: Headers, prerender?: Prerender, analytics?: Analytics, };

export type Site = { 
/**
 * `https://example.com`, no trailing slash, no path.
 */
origin: string, name: string, 
/**
 * BCP 47 language tag.
 */
language: string, };

export type IdentityKind = "person" | "organization";

export type Identity = { kind: IdentityKind, name: string, url: string, sameAs: Array<string>, organization?: Organization, };

export type Organization = { name: string, url: string, };

export type ContentSignal = { search: boolean, aiInput: boolean, aiTrain: boolean, };

export type BotGroup = "search" | "user" | "training" | "other";

export type BotPolicy = { tokens: Array<string>, allow: Array<string>, disallow: Array<string>, group: BotGroup, };

export type Content = { 
/**
 * CSS selector of the main content element.
 */
mainSelector: string, 
/**
 * Route globs that get no twin and are left out of llms/sitemap.
 */
exclude: Array<string>, 
/**
 * Route glob → source path globs (relative to the site directory). A
 * page matching a route glob takes the newest commit date of those
 * sources as its lastmod: built output is usually not tracked by git.
 */
sources: { [key in string]: Array<string> }, };

export type Llms = { summary: string, sections: Array<LlmsSection>, };

export type LlmsSection = { title: string, 
/**
 * Route globs, matched against page routes in page order.
 */
routes: Array<string>, };

export type Headers = { 
/**
 * Path globs of content-hashed assets.
 */
immutable: Array<string>, };

export type Prerender = { routes: Array<string>, };

export type Analytics = { 
/**
 * Cloudflare Web Analytics (`cf-web-analytics`): true extends the site's
 * CSP so the beacon Cloudflare injects can load and report.
 */
cloudflareWebAnalytics: boolean, };

export type SiteInput = { config: SiteConfig, 
/**
 * Commit SHA.
 */
buildId: string, 
/**
 * Host names the site is served on (the action's `domains`, lower case,
 * no port); each gets its own tagged rewrite rules. Includes the
 * origin's host.
 */
hosts: Array<string>, 
/**
 * Only the names in `config.env`; the core re-checks.
 */
env: { [key in string]: string }, pages: Array<PageInput>, existing: Existing, 
/**
 * Newest commit date (`YYYY-MM-DDTHH:MM:SSZ`, UTC) of each source glob
 * of `config.content.sources` that matched a committed file; a glob
 * matching none is left out.
 */
sourceLastmod: { [key in string]: string }, };

export type Existing = { robots?: string, headers?: string, llms?: string, sitemap?: string, };

export type PageInput = { 
/**
 * `"/"`, `"/about/"`.
 */
route: string, 
/**
 * Output-relative path: `"index.html"`, `"about/index.html"`.
 */
file: string, html: string, 
/**
 * Adapter-supplied source markdown (preferred over conversion).
 */
markdown?: string, 
/**
 * ISO 8601 from git, never "now".
 */
lastmod?: string, };

export type SiteOutput = { files: Array<OutFile>, rewriteRules: Array<RewriteRule>, pages: Array<PageSummary>, warnings: Array<CoreError>, };

export type OutFile = { file: string, contents: string, };

export type RewriteRule = { description: string, expression: string, pathExpression: string, };

export type PageSummary = { route: string, markdownFile: string, title: string, description: string, tokens: number, lastmod?: string, };

export type LiveCheckInput = { config?: SiteConfig, origin?: string, routes: Array<string>, buildId?: string, };

export type LiveRequest = { url: string, userAgent: string, accept: string, expect: LiveExpect, };

export type LiveExpect = { status: number, contentType?: string, varyIncludes?: string, bodyIncludes?: string, };

export type LiveObservation = { url: string, userAgent: string, accept: string, status: number, headers: { [key in string]: string }, bodyPrefix: string, 
/**
 * The end of the body (same length bound as the prefix): edge-injected
 * scripts such as the Web Analytics beacon sit before `</body>`.
 */
bodySuffix: string, };

export type AuditInput = { config: SiteConfig, 
/**
 * The deployed commit; the live build-meta check compares against it.
 */
buildId: string, pages: Array<AuditPage>, robots: string, headers: string, llms?: string, sitemap: string, 
/**
 * Present only for the post-deploy audit.
 */
live?: Array<LiveObservation>, };

export type AuditPage = { route: string, html: string, markdown: string, };

export type LiveAuditInput = { 
/**
 * `https://host`, no path.
 */
origin: string, 
/**
 * Routes sampled for the Accept matrix (`/` is always included).
 */
routes: Array<string>, buildId?: string, live: Array<LiveObservation>, };

export type AuditReport = { 
/**
 * 0–100, weighted over the categories that had findings.
 */
score: number, categories: Array<CategoryScore>, findings: Array<Finding>, };

export type CategoryScore = { id: string, title: string, weight: number, score: number, };

export type Severity = "blocking" | "advisory";

export type Finding = { checkId: string, title: string, 
/**
 * Blocking ⇔ grade A/B access/indexability evidence.
 */
severity: Severity, passed: boolean, route?: string, evidence: string, 
/**
 * Ids from CITATIONS.md.
 */
citations: Array<string>, };

export type RagInput = { config: SiteConfig, pages: Array<PageSummary>, html: Array<RouteHtml>, };

export type RouteHtml = { route: string, html: string, };

export type RagOutput = { sidecar: { [key in string]: SidecarEntry }, edges: Array<Edge>, };

export type SidecarEntry = { url: string, title: string, lastmod?: string, };

export type Edge = { from: EdgeEnd, to: EdgeEnd, relation: Relation, weight: number, };

export type EdgeEnd = { path: string, };

export type Relation = "child_of" | "links_to";

/** UTF-16 code units of each live body's start and end the host keeps for the core (core: live::BODY_PREFIX_CHARS). */
export const BODY_PREFIX_CHARS = 8192;
